package objectstore

import (
	"context"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
	"time"
)

// ErrInvalidKey is returned for an object key outside the allowed form.
var ErrInvalidKey = errors.New("objectstore: invalid object key")

// maxKeyLen bounds a key well below every backend's limit.
const maxKeyLen = 512

// ValidKey enforces the one key form every driver accepts: lower-case
// letters, digits, '-', '.' and '/', split into non-empty segments that do
// not start with a dot. Keys are generated by the application from random
// identifiers, so the rule costs nothing; for the filesystem driver it is
// also what makes path traversal ("..", absolute paths, drive letters,
// backslashes) impossible.
func ValidKey(key string) error {
	if key == "" || len(key) > maxKeyLen {
		return ErrInvalidKey
	}
	for _, r := range key {
		if !(r >= 'a' && r <= 'z' || r >= '0' && r <= '9' || r == '-' || r == '.' || r == '/') {
			return ErrInvalidKey
		}
	}
	for _, seg := range strings.Split(key, "/") {
		if seg == "" || strings.HasPrefix(seg, ".") {
			return ErrInvalidKey
		}
	}
	return nil
}

// FSStore keeps objects as files under <root>/<bucket>/<key>. It exists for
// development machines without MinIO; config.Load refuses it in production.
type FSStore struct {
	dir string // absolute <root>/<bucket>
}

var _ Blob = (*FSStore)(nil)

// OpenFS creates the bucket directory if needed. The bucket name follows
// the key rule with no '/'.
func OpenFS(root, bucket string) (*FSStore, error) {
	if root == "" {
		return nil, errors.New("objectstore: filesystem root is required")
	}
	if ValidKey(bucket) != nil || strings.Contains(bucket, "/") {
		return nil, fmt.Errorf("objectstore: invalid bucket name %q", bucket)
	}
	abs, err := filepath.Abs(root)
	if err != nil {
		return nil, fmt.Errorf("objectstore: resolve root: %w", err)
	}
	dir := filepath.Join(abs, bucket)
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return nil, fmt.Errorf("objectstore: create bucket directory: %w", err)
	}
	return &FSStore{dir: dir}, nil
}

// path maps a validated key to a file inside the bucket directory. The
// containment check repeats the guarantee ValidKey gives, so a future change
// to the key rule cannot silently open a traversal.
func (s *FSStore) path(key string) (string, error) {
	if err := ValidKey(key); err != nil {
		return "", err
	}
	p := filepath.Join(s.dir, filepath.FromSlash(key))
	rel, err := filepath.Rel(s.dir, p)
	if err != nil || rel == "." || strings.HasPrefix(rel, "..") || filepath.IsAbs(rel) {
		return "", ErrInvalidKey
	}
	return p, nil
}

// Put writes the object through a temporary file and a rename, so a reader
// never sees a partial object and a short body leaves nothing behind.
func (s *FSStore) Put(ctx context.Context, key string, r io.Reader, size int64, _ string) error {
	p, err := s.path(key)
	if err != nil {
		return err
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	if err := os.MkdirAll(filepath.Dir(p), 0o700); err != nil {
		return fmt.Errorf("put object: %w", err)
	}
	tmp, err := os.CreateTemp(filepath.Dir(p), ".put-*")
	if err != nil {
		return fmt.Errorf("put object: %w", err)
	}
	committed := false
	defer func() {
		if !committed {
			_ = tmp.Close()
			_ = os.Remove(tmp.Name())
		}
	}()
	n, err := io.Copy(tmp, io.LimitReader(r, size+1))
	if err != nil {
		return fmt.Errorf("put object: %w", err)
	}
	if n != size {
		return fmt.Errorf("put object: body is %d bytes, expected %d", n, size)
	}
	if err := tmp.Sync(); err != nil {
		return fmt.Errorf("put object: %w", err)
	}
	if err := tmp.Close(); err != nil {
		return fmt.Errorf("put object: %w", err)
	}
	if err := os.Rename(tmp.Name(), p); err != nil {
		return fmt.Errorf("put object: %w", err)
	}
	committed = true
	return nil
}

// Get opens the object file.
func (s *FSStore) Get(_ context.Context, key string) (io.ReadCloser, int64, error) {
	p, err := s.path(key)
	if err != nil {
		return nil, 0, err
	}
	f, err := os.Open(p)
	if errors.Is(err, fs.ErrNotExist) {
		return nil, 0, ErrNotFound
	}
	if err != nil {
		return nil, 0, fmt.Errorf("get object: %w", err)
	}
	info, err := f.Stat()
	if err != nil || !info.Mode().IsRegular() {
		_ = f.Close()
		return nil, 0, ErrNotFound
	}
	return f, info.Size(), nil
}

// Check reports whether the bucket directory exists.
func (s *FSStore) Check(_ context.Context, _ time.Duration) error {
	info, err := os.Stat(s.dir)
	if err != nil {
		return fmt.Errorf("object storage not ready: %w", err)
	}
	if !info.IsDir() {
		return fmt.Errorf("object storage bucket path is not a directory")
	}
	return nil
}
